const DESKTOP = "apps/desktop";
const STYLES_DIR = `${DESKTOP}/src/styles`;
const SRC_DIR = `${DESKTOP}/src`;

const PALETTE =
  "slate|gray|grey|zinc|neutral|stone|red|orange|amber|yellow|lime|green|emerald|teal|cyan|sky|blue|indigo|violet|purple|fuchsia|pink|rose";
const COLOR_PREFIX =
  "text|bg|border|ring|fill|stroke|from|to|via|divide|outline|decoration|caret|placeholder|accent";

// Class shapes normally generated by Tailwind rather than authored CSS.
const UTILITY_MATCHERS = [
  /^-?(p|px|py|pt|pb|pl|pr|ps|pe|m|mx|my|mt|mb|ml|mr|ms|me|gap|space)(-(x|y))?-.+$/,
  /^(w|h|min-w|max-w|min-h|max-h|size|basis)-.+$/,
  /^(flex|grid|inline-flex|inline-grid|inline-block|block|inline|hidden|table|contents)$/,
  /^(order|col|row|auto-cols|auto-rows|place|content|items|justify|self|grid-cols|grid-rows|grid-flow)-.+$/,
  /^(flex-1|flex-auto|flex-none|flex-col|flex-row|flex-row-reverse|flex-col-reverse|flex-wrap|flex-nowrap|grow|grow-0|shrink|shrink-0)$/,
  /^text-(xs|sm|base|lg|xl|[2-9]xl)$/,
  /^text-\[.+\]$/,
  /^font-(thin|extralight|light|normal|medium|semibold|bold|extrabold|black)$/,
  /^(leading|tracking)-.+$/,
  /^(uppercase|lowercase|capitalize|normal-case|italic|not-italic|truncate|antialiased|tabular-nums|slashed-zero)$/,
  /^(underline|line-through|no-underline|overline)$/,
  /^text-(left|center|right|justify|start|end)$/,
  /^whitespace-.+$/,
  /^(break-words|break-all|break-normal|break-keep)$/,
  /^(text-ellipsis|text-clip|text-nowrap|text-wrap|text-balance)$/,
  /^rounded(-.+)?$/,
  /^border(-(0|2|4|8|t|b|l|r|x|y|s|e))?$/,
  /^(shadow|opacity|blur|brightness|backdrop)-.+$/,
  /^shadow$/,
  /^(absolute|relative|fixed|sticky|static)$/,
  /^(inset|top|bottom|left|right|z)-.+$/,
  /^(overflow|overscroll|cursor|select|resize|object|aspect|columns|float|clear|box|isolation)-.+$/,
  /^(pointer-events-none|pointer-events-auto|cursor-pointer)$/,
  /^(transition|duration|delay|ease|animate)-.+$/,
  /^transition$/,
  /^(scale|rotate|translate|skew|origin)-.+$/,
  /^list-.+$/,
  /^divide-.+$/,
  new RegExp(`^(${COLOR_PREFIX})-(${PALETTE})(-\\d{2,3})?$`),
  new RegExp(`^(${COLOR_PREFIX})-[a-z0-9-]+\\/\\d{1,3}$`),
  // Catch standalone utilities that have no prefix-dash shape.
  /^(sr-only|not-sr-only|container|prose|isolate|invisible|visible|collapse)$/,
];

function isUtilityShape(token) {
  return UTILITY_MATCHERS.some((re) => re.test(token));
}

// Handwritten selectors under src/styles allow matching utility-shaped tokens;
// other utility tokens are dead.
function loadDefinedClasses(read, listFiles) {
  const defined = new Set();
  for (const file of listFiles(STYLES_DIR, (f) => f.endsWith(".css"))) {
    for (const match of read(file).matchAll(/\.(-?[a-zA-Z_][a-zA-Z0-9_\\/-]*)/g)) {
      defined.add(match[1].replace(/\\/g, ""));
    }
  }
  return defined;
}

function objectLiteralEnd(source, start) {
  let depth = 0;
  let quote = null;
  let escaped = false;
  for (let index = start; index < source.length; index += 1) {
    const character = source[index];
    if (quote) {
      if (escaped) escaped = false;
      else if (character === "\\") escaped = true;
      else if (character === quote) quote = null;
      continue;
    }
    if (character === '"' || character === "'" || character === "`") {
      quote = character;
    } else if (character === "{") {
      depth += 1;
    } else if (character === "}" && --depth === 0) {
      return index;
    }
  }
  return source.length;
}

function stringLiterals(source) {
  return [...source.matchAll(/"([^"]*)"|'([^']*)'|`([^`]*)`/g)].map(
    (match) => match[1] ?? match[2] ?? match[3] ?? "",
  );
}

function namedObjectLiteralStart(source, afterName) {
  const tail = source.slice(afterName, afterName + 512);
  const equalsOffset = tail.indexOf("=");
  if (equalsOffset === -1) return null;
  const beforeEquals = tail.slice(0, equalsOffset);
  if (beforeEquals.includes(";") || /\b(?:const|let)\b/.test(beforeEquals)) return null;

  let cursor = afterName + equalsOffset + 1;
  while (/\s/.test(source[cursor] ?? "")) cursor += 1;
  if (source.startsWith("Object.freeze", cursor)) {
    cursor += "Object.freeze".length;
    while (/\s/.test(source[cursor] ?? "")) cursor += 1;
    if (source[cursor] !== "(") return null;
    cursor += 1;
    while (/\s/.test(source[cursor] ?? "")) cursor += 1;
  }
  return source[cursor] === "{" ? cursor : null;
}

function extractNamedClassMapStrings(source) {
  const values = [];
  const declaration = /\b(?:const|let)\s+([A-Z][A-Z0-9_]*)\b/g;
  for (const match of source.matchAll(declaration)) {
    const name = match[1];
    if (!/(?:CLASS(?:ES)?|STYLES?|COLORS?|ACCENT|DOT|BORDERS?|BG|TEXT)(?:_MAP)?$/.test(name)) {
      continue;
    }
    const start = namedObjectLiteralStart(source, (match.index ?? 0) + match[0].length);
    if (start === null) continue;
    values.push(...stringLiterals(source.slice(start + 1, objectLiteralEnd(source, start))));
  }
  return values;
}

// Extract JSX and object class strings, blanking template holes before token
// matching.
function extractClassStrings(source) {
  const out = extractNamedClassMapStrings(source);
  const re = /className\s*[:=]\s*/g;
  while (re.exec(source) !== null) {
    let i = re.lastIndex;
    while (i < source.length && /\s/.test(source[i])) i++;
    const ch = source[i];
    if (ch === '"' || ch === "'" || ch === "`") {
      let j = i + 1;
      while (j < source.length && source[j] !== ch) j++;
      out.push(source.slice(i + 1, j).replace(/\$\{[^}]*\}/g, " "));
    } else if (ch === "{") {
      let depth = 0;
      let j = i;
      for (; j < source.length; j++) {
        if (source[j] === "{") depth++;
        else if (source[j] === "}" && --depth === 0) {
          j++;
          break;
        }
      }
      const expr = source.slice(i + 1, j - 1);
      const literal = /"([^"]*)"|'([^']*)'|`([^`]*)`/g;
      let lit;
      while ((lit = literal.exec(expr))) {
        out.push((lit[1] ?? lit[2] ?? lit[3] ?? "").replace(/\$\{[^}]*\}/g, " "));
      }
    }
  }
  return out;
}

function deadUtilityFailures(read, listFiles) {
  const defined = loadDefinedClasses(read, listFiles);
  const failures = [];
  const sources = listFiles(
    SRC_DIR,
    (f) => /\.(tsx|ts)$/.test(f) && !/\.(test|spec)\.(tsx|ts)$/.test(f),
  );
  for (const file of sources) {
    const dead = new Set();
    for (const value of extractClassStrings(read(file))) {
      for (const raw of value.split(/\s+/)) {
        const token = raw.replace(/^([a-z0-9-]+:)+/i, ""); // strip variant: prefixes
        if (token && !defined.has(token) && isUtilityShape(token)) dead.add(token);
      }
    }
    if (dead.size) {
      failures.push(
        `${file} uses Tailwind utilities with no backing CSS rule: ${[...dead]
          .sort()
          .join(" ")}. Add a semantic class in src/styles or use an existing one.`,
      );
    }
  }
  return failures;
}

function reintroductionFailures(read, listFiles, exists) {
  const failures = [];

  const pkg = JSON.parse(read(`${DESKTOP}/package.json`));
  const deps = { ...(pkg.dependencies ?? {}), ...(pkg.devDependencies ?? {}) };
  for (const name of ["tailwindcss", "@tailwindcss/vite", "tailwind-merge", "tw-animate-css"]) {
    if (name in deps) {
      failures.push(
        `${DESKTOP}/package.json declares "${name}" - Tailwind was removed and must stay uninstalled.`,
      );
    }
  }

  const bannedAtRules = /^\s*@(tailwind|apply|theme|custom-variant)\b/m;
  const bannedImport = /^\s*@import\s+["'](tailwindcss|tw-animate-css)["']/m;
  // Scan every source stylesheet, including the index entrypoint.
  for (const file of listFiles(SRC_DIR, (f) => f.endsWith(".css"))) {
    const css = read(file);
    if (bannedAtRules.test(css) || bannedImport.test(css)) {
      failures.push(
        `${file} contains a Tailwind-only at-rule (@tailwind/@apply/@theme/@custom-variant or an @import of tailwindcss) - these must stay removed.`,
      );
    }
  }

  const viteConfig = `${DESKTOP}/vite.config.ts`;
  if (exists(viteConfig) && /@tailwindcss\/vite/.test(read(viteConfig))) {
    failures.push(
      `${viteConfig} references @tailwindcss/vite - the Tailwind Vite plugin must stay removed.`,
    );
  }

  return failures;
}

export function tailwindRemovalFailures(read, listFiles, exists) {
  return [
    ...deadUtilityFailures(read, listFiles),
    ...reintroductionFailures(read, listFiles, exists),
  ];
}
